#pragma once
// Display colour only; waveform counts and source pixels are never sampled.
static uint32_t packColourMean(double r,double g,double b){double peak=std::max({r,g,b});if(!peak)return 0;int e=int(std::max(-16.,std::floor(std::log2(peak))))+16;double step=std::ldexp(1.,e-24);if(std::floor(peak/step+.5)==512){e++;step*=2;}return uint32_t(std::floor(r/step+.5))|(uint32_t(std::floor(g/step+.5))<<9)|(uint32_t(std::floor(b/step+.5))<<18)|(uint32_t(e)<<27);}
static std::vector<uint8_t> adaptiveWaveColour(const std::vector<uint32_t>&wave,const std::vector<uint32_t>&rgb){const size_t n=wave.size();if(n%1024||rgb.size()!=n*3)throw std::runtime_error("Invalid adaptive colour grid");const uint32_t width=512,height=n/512;std::vector<uint8_t>out(8);uint32_t tiles=0;int64_t previous=-1;
 auto word=[&](uint32_t v){for(int k=0;k<4;k++)out.push_back(uint8_t(v>>(8*k)));};auto var=[&](uint32_t v){while(v>=128){out.push_back(uint8_t(v)|128);v>>=7;}out.push_back(uint8_t(v));};
 for(uint32_t y=0;y<height;y+=2)for(uint32_t x=0;x<width;x+=2){uint32_t ix[4]{},mask=0;uint64_t sum[3]{},count=0;double lo=INFINITY,hi=0;for(uint32_t bit=0;bit<4;bit++){size_t i=(y+(bit>>1))*width+x+(bit&1);ix[bit]=i;uint32_t peak=std::max({rgb[i],rgb[n+i],rgb[2*n+i]});if(!peak)continue;if(!wave[i]||uint64_t(peak)>uint64_t(wave[i])*255)throw std::runtime_error("Invalid source-colour sum");mask|=1u<<bit;count+=wave[i];for(int ch=0;ch<3;ch++)sum[ch]+=rgb[ch*n+i];double brightness=double(peak)/wave[i];lo=std::min(lo,brightness);hi=std::max(hi,brightness);}if(!mask)continue;
  double peak=double(std::max({sum[0],sum[1],sum[2]}));bool merge=hi<=lo*1.005;for(uint32_t bit=0;bit<4;bit++)if(mask&(1u<<bit)){auto i=ix[bit];double p=std::max({rgb[i],rgb[n+i],rgb[2*n+i]});for(int ch=0;ch<3;ch++)if(std::abs(double(rgb[ch*n+i])/p-double(sum[ch])/peak)>1./510)merge=false;}
  uint32_t tile=(y/2)*(width/2)+x/2;var(uint32_t(tile-previous));previous=tile;out.push_back(uint8_t(mask|(merge?16:0)));if(merge)word(packColourMean(double(sum[0])/count*256,double(sum[1])/count*256,double(sum[2])/count*256));else for(uint32_t bit=0;bit<4;bit++)if(mask&(1u<<bit)){auto i=ix[bit];word(packColourMean(double(rgb[i])/wave[i]*256,double(rgb[n+i])/wave[i]*256,double(rgb[2*n+i])/wave[i]*256));}tiles++;
 }out[0]=3;for(int k=0;k<4;k++)out[4+k]=uint8_t(tiles>>(8*k));return out;
}
